// Harness for utils::qprocess::run
// - Provides an Events type with required callbacks and quits a nested event loop on completion
// - Picks a short-lived candidate command without QFileInfo dependency; handles FailedToStart gracefully
// - Caps runtime with a guard timer to avoid hanging when nothing happens
{
    struct Events {
        QEventLoop *loop = nullptr;
        int created = 0;
        int started = 0;
        int done = 0;
        int errors = 0;
        bool failedToStart = false;
        qint64 data_bytes = 0;
        int last_exit_code = -1;
        QProcess::ExitStatus last_exit_status = QProcess::ExitStatus::NormalExit;
        void whenCreated(QProcess &){ created++; }
        void whenStarted(QProcess &){ started++; }
        void withData(QProcess::ProcessChannel, const QByteArray &b){ data_bytes += b.size(); }
        void withError(QProcess::ProcessError e){ errors++; failedToStart = (e == QProcess::ProcessError::FailedToStart); }
        void whenDone(int code, QProcess::ExitStatus status){
            last_exit_code = code;
            last_exit_status = status;
            done++;
            if (loop) { loop->quit(); }
        }
    } events;

    // Candidate commands: prefer very short-lived ones; if not present, FailedToStart is acceptable
    QStringList candidates;
    candidates << "/bin/true" << "/usr/bin/true" << "/bin/echo" << "/usr/bin/echo" << "/bin/printf" << "/usr/bin/printf" << "cmd.exe";

    unsigned int pick = *FUZZ_PARAM(unsigned int);
    QString program = candidates.at(static_cast<int>(pick % static_cast<unsigned int>(candidates.size())));

    QStringList arguments;

    // If the program name suggests echo/printf, add a small fuzz argument
    QString lower = program.toLower();
    if (lower.contains("echo")) {
        std::string s = FUZZ_PARAM_STR();
        if (s.size() > 64) s.resize(64);
        arguments << QString::fromUtf8(s.data(), static_cast<int>(s.size()));
    } else if (lower.contains("printf")) {
        std::string s = FUZZ_PARAM_STR();
        if (s.size() > 64) s.resize(64);
        arguments << QString::fromUtf8(s.data(), static_cast<int>(s.size())) << "\n";
    } else if (lower.endsWith("cmd.exe")) {
        // Windows fallback: ensure a fast exit
        arguments << "/c" << "exit" << "0";
    }

    // Add up to 2 small extra fuzz arguments to exercise argument handling
    unsigned int extra_argc = *FUZZ_PARAM(unsigned int) % 3;
    for (unsigned int i = 0; i < extra_argc; ++i) {
        std::string a = FUZZ_PARAM_STR();
        if (a.size() > 32) a.resize(32);
        arguments << QString::fromUtf8(a.data(), static_cast<int>(a.size()));
    }

    // Ensure a running event loop and time-bounded execution
    QEventLoop loop;
    events.loop = &loop;

    QTimer guard;
    guard.setSingleShot(true);
    QObject::connect(&guard, &QTimer::timeout, &loop, &QEventLoop::quit);
    guard.start(300);

    // Invoke target asynchronously; all callbacks will occur on this thread's event loop
    utils::qprocess::run(program, arguments, events);

    // Drive the nested loop until completion or timeout
    loop.exec();

    // Post-conditions:
    // - If the process failed to start, we expect at least one error callback; completion is not guaranteed.
    if (events.failedToStart) {
        FUZZ_ASSERT(events.errors >= 1, "FailedToStart should trigger an error callback");
    } else {
