        FUZZ_ASSERT(events.done == 1, "Completion should be signaled exactly once");
        // - Exit status must be coherent per Qt contract
        FUZZ_ASSERT(events.last_exit_status == QProcess::NormalExit || events.last_exit_status == QProcess::CrashExit,
                    "Exit status must be NormalExit or CrashExit");
