import random
import struct
import string
from typing import List

# Target data type: command-line arguments (argv strings), consumed by FUZZ_PARAM_STR in the stub
# The stub uses up to 3 FUZZ_PARAM_STR calls (one main for echo/printf, then up to 2 small extras).
# Provide a bytes buffer that, when split into strings by the fuzzing framework,
# yields interesting but valid small UTF-8-ish strings, including edge cases for echo/printf and generic args.
# Assumptions about the harness deserializer:
# - It likely pulls variable-length strings from the byte stream. We avoid malformed encodings by staying in UTF-8.
# - Keep total size <= 4096 bytes.
# Strategy:
# - Construct a sequence of length-prefixed segments to be robust: [len32][data]... so generic frameworks can parse.
# - Include diverse strings:
#   * ASCII printable, spaces, quotes, backslashes
#   * Shell-like switches, format specifiers for printf, percent-heavy patterns
#   * Unicode/UTF-8 multi-byte sequences
#   * Empty string and very short strings
#   * Binary-like bytes
# - Randomize choices and lengths, but keep each string <= 64 bytes (stub truncates to 64/32 anyway).

MAX_TOTAL = 4096

ASCII = string.ascii_letters + string.digits
PUNCT = "-_./,:;!@#$^&*()[]{}?\"'`|\"\\"
SPACES = " \t\n"

PRINTF_TEMPLATES = [
    "%s", "%d", "%x", "%ld", "%zu", "%p", "%.*s", "%#08x", "%1$s %2$d", "%%", "%n",
]

UNICODE_SAMPLES = [
    "føø", "こんにちは", "😀", "𝔘𝔫𝔦𝔠𝔬𝔡𝔢", "mañana", "друг", "العربية", "हिन्दी", "คอมพิวเตอร์",
]

ECHO_SAMPLES = [
    "hello world", " spaced  words ", "--", "-n", "-e", "\\tTabbed\\nLine", "quotes '" ' and "\"double\"',
]

BINARY_SAMPLES = [
    bytes([0, 1, 2, 3, 255, 0x7F, 0x80, 0xFE, 10, 0]),
]

SHELLY = ["--help", "-v", "-O2", "--long-option=value", "name=value", "..", "/", "./-weird", "--", "-\"q\"",]


def _rand_ascii(r: random.Random, n: int) -> str:
    pool = ASCII + PUNCT + SPACES
    return "".join(r.choice(pool) for _ in range(n))


def _rand_printf(r: random.Random) -> str:
    # Mix template with filler to exercise printf-like behavior
    t = r.choice(PRINTF_TEMPLATES)
    # Surround with noise to avoid pure format string if consumer prints
    prefix = _rand_ascii(r, r.randint(0, 6))
    suffix = _rand_ascii(r, r.randint(0, 6))
    return prefix + t + suffix


def _rand_unicode(r: random.Random) -> str:
    base = r.choice(UNICODE_SAMPLES)
    # Repeat or mix with ASCII
    extra = _rand_ascii(r, r.randint(0, 6))
    if r.random() < 0.5:
        return base + extra
    return extra + base


def _rand_echo(r: random.Random) -> str:
    if r.random() < 0.5:
        return r.choice(ECHO_SAMPLES)
    # construct with spaces and quotes
    parts = [r.choice(["-n", "-e", "--", ""]) , _rand_ascii(r, r.randint(0, 8)), '"' + _rand_ascii(r, r.randint(0, 6)) + '"']
    return " ".join(p for p in parts if p)


def _rand_binary(r: random.Random, max_len: int) -> bytes:
    base = bytearray(r.choice(BINARY_SAMPLES))
    # Extend with random bytes
    extra = r.randint(0, max_len - len(base)) if max_len > len(base) else 0
    for _ in range(extra):
        base.append(r.randrange(0, 256))
    return bytes(base)


def _cap_utf8(b: bytes, limit: int) -> bytes:
    # Truncate to limit; ensure result is not splitting a multibyte UTF-8 sequence by backing off as needed.
    if len(b) <= limit:
        return b
    b = b[:limit]
    # Backtrack until valid UTF-8 prefix or give up to raw bytes
    for back in range(4):
        try:
            b[: len(b) - back].decode('utf-8')
            return b[: len(b) - back]
        except UnicodeDecodeError:
            pass
    return b  # if still invalid, let it be bytes


def _emit_len_prefixed(chunks: List[bytes]) -> bytes:
    out = bytearray()
    for c in chunks:
        out += struct.pack('<I', len(c))
        out += c
    return bytes(out)


def _make_arg(r: random.Random) -> bytes:
    kind = r.choices(
        population=["ascii", "printf", "unicode", "echo", "shell", "binary", "empty", "short"],
        weights=[20, 12, 12, 10, 12, 8, 6, 20],
        k=1,
    )[0]

    if kind == "ascii":
        s = _rand_ascii(r, r.randint(1, 48))
        return s.encode('utf-8', errors='ignore')
    if kind == "printf":
        s = _rand_printf(r)
        s = s[:48]
        return s.encode('utf-8', errors='ignore')
    if kind == "unicode":
        s = _rand_unicode(r)
        s = s[:48]
        return s.encode('utf-8', errors='ignore')
    if kind == "echo":
        s = _rand_echo(r)
        s = s[:64]
        return s.encode('utf-8', errors='ignore')
    if kind == "shell":
        # Combine a shell-like token with noise
        s = r.choice(SHELLY)
        if r.random() < 0.6:
            s += "=" + _rand_ascii(r, r.randint(0, 12))
        return s[:48].encode('utf-8', errors='ignore')
    if kind == "binary":
        return _rand_binary(r, 48)
    if kind == "empty":
        return b""
    if kind == "short":
        return _rand_ascii(r, r.randint(1, 4)).encode('utf-8', errors='ignore')
    return b"x"


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # We will create between 3 and 8 candidate strings, enough for primary + extras
    count = r.randint(3, 8)
    chunks: List[bytes] = []

    # Bias first argument towards echo/printf-interesting content to match harness behavior when command is echo/printf
    first_kind = r.random()
    if first_kind < 0.4:
        first = _rand_echo(r).encode('utf-8', errors='ignore')
    elif first_kind < 0.75:
        first = _rand_printf(r).encode('utf-8', errors='ignore')
    else:
        first = _make_arg(r)
    first = _cap_utf8(first, 64)
    chunks.append(first)

    for _ in range(count - 1):
        arg = _make_arg(r)
        arg = _cap_utf8(arg, 64)
        chunks.append(arg)

    # Ensure total size cap; drop trailing chunks if needed
    # Account for 4-byte length prefix per chunk
    total = 0
    kept: List[bytes] = []
    for c in chunks:
        need = 4 + len(c)
        if total + need > MAX_TOTAL:
            break
        kept.append(c)
        total += need

    return _emit_len_prefixed(kept)
